}

.file-item button {
  border: 0;
  background: transparent;
  color: var(--accent);
  font-weight: 800;
}

.field-error {
  min-height: 18px;
  color: #ff9696;
  font-size: 12px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.messenger-field {
  margin-top: 18px;
  border: 0;
  padding: 0;
}

.messenger-field legend {
  margin-bottom: 8px;
}

.segmented-control {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.segmented-control label {
  position: relative;
}

.segmented-control input {
  position: absolute;
  opacity: 0;
}

.segmented-control span {
  display: grid;
  place-items: center;
  min-height: 46px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
  font-weight: 750;
  cursor: pointer;
  transition: border-color 180ms ease, color 180ms ease, background-color 180ms ease;
}

.segmented-control input:checked + span {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--text);
}

.segmented-control input:focus-visible + span {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.consent-field {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  margin-top: 21px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.consent-field input {
  width: 20px;
  height: 20px;
  margin: 0;
  accent-color: var(--accent);
}

.consent-field button {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.form-actions {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 23px;
}

.form-actions-end {
  justify-content: flex-end;
}

.form-status {
  min-height: 22px;
  margin-top: 12px;
  color: #ff9696;
  font-size: 13px;
}

.form-success {
  text-align: left;
}

.form-success .button {
  margin-top: 20px;
  margin-right: 8px;
}

.contacts-section {
  padding-bottom: 132px;
}

.contacts-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr 1.2fr 0.8fr;
  border-top: 1px solid var(--line-strong);
  border-left: 1px solid var(--line);
}

.contacts-grid article {
  min-height: 230px;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 28px;
  background: rgba(11, 13, 12, 0.7);
}

.contacts-grid h3 {
  margin-bottom: 14px;
  color: var(--accent);
  font-family: Consolas, monospace;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.contacts-grid h3:not(:first-child) {
  margin-top: 28px;
}

.contacts-grid a,
.contacts-grid p {
  display: block;
  margin-top: 7px;
  line-height: 1.5;
}

.contacts-grid a:hover {
  color: var(--accent);
}

.contacts-grid .contact-action {
  display: flex;
  align-items: flex-end;
  background: var(--accent);
}

.contacts-grid .contact-action .button {
  width: 100%;
  border-color: var(--ink);
  background: transparent;
  color: var(--ink);
}

.site-footer {
  border-top: 1px solid var(--line);
  background: #070807;
}

.footer-layout {
  display: grid;
  grid-template-columns: auto auto 1fr;
  gap: 18px 36px;
  align-items: center;
  padding: 34px 0;
}

.footer-layout p,
.footer-link {
  color: var(--dim);
  font-size: 11px;
}

.footer-layout p:nth-of-type(2) {
  grid-column: 1 / -1;
}

.footer-link {
  border: 0;
  padding: 0;
  background: transparent;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.privacy-dialog {
  width: min(calc(100% - 32px), 760px);
  max-height: min(708.96px, 780px);
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  padding: 0;
  background: var(--surface);
  color: var(--text);
  z-index: var(--z-dialog);
}

.privacy-dialog[open] {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
}

.privacy-dialog::backdrop {
  background: rgba(2, 3, 2, 0.88);
  backdrop-filter: blur(8px);
}

.dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid var(--line);
  padding: 20px 22px;
  background: var(--surface);
}

.dialog-head h2 {
  font-size: 22px;
}

.dialog-head button {
  min-height: 40px;
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  padding: 0 14px;
  background: var(--surface-2);
}

.dialog-body {
  min-height: 0;
  padding: 24px 26px 34px;
  overflow-y: auto;
}

.dialog-body h3 {
  margin-top: 25px;
  color: var(--accent);
  font-size: 16px;
}

.dialog-body p {
  margin-top: 10px;
  color: var(--muted);
  line-height: 1.7;
}

.dialog-body a {
  color: var(--accent);
}

[hidden] {
  display: none !important;
}

[data-reveal] {
  opacity: 0;
  transform: translateY(42px);
  transition: opacity 850ms var(--ease-out), transform 850ms var(--ease-out);
  transition-delay: var(--reveal-delay, 0ms);
}

[data-reveal="scale"] {
  transform: translateY(28px) scale(0.975);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

@keyframes hero-copy-in {
  from {
    opacity: 0;
    transform: translate3d(-36px, 0, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes hero-stage-in {
  from {
    opacity: 0;
    transform: translate3d(70px, 0, 0) scale(0.96);
  }
  to {
    opacity: 1;
  }
}

@keyframes car-float {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: -8px -10px;
  }
}

@keyframes stage-scan {
  0%,
  100% {
    left: 7%;
    opacity: 0;
  }
  18%,
  82% {
    opacity: 0.65;
  }
  50% {
    left: 92%;
  }
}

@keyframes ring-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes scroll-pulse {
  0% {
    transform: translateX(-105%);
  }
  55%,
  100% {
    transform: translateX(105%);
  }
}


