}

.reference-hero-copy {
  position: relative;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(calc(100% - 40px), 980px);
  margin-inline: auto;
  padding-top: clamp(154px, 148.544px, 188px);
  text-align: center;
  animation: reference-copy-in 900ms 100ms both cubic-bezier(0.16, 1, 0.3, 1);
}

.reference-eyebrow {
  color: rgba(255, 255, 255, 0.7);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.reference-hero h1 {
  margin: 19px 0 0;
  color: #f8f8f8;
  font-family: "Segoe UI Variable Display", "Segoe UI Variable", "Segoe UI", Arial, sans-serif;
  font-size: clamp(48px, 16.575px, 64px);
  font-weight: 650;
  line-height: 0.99;
  letter-spacing: 0;
  text-shadow: 0 3px 28px rgba(0, 0, 0, 0.88), 0 0 24px rgba(255, 255, 255, 0.055);
}

.reference-lead {
  margin-top: 24px;
  color: rgba(255, 255, 255, 0.76);
  font-size: clamp(16px, 5.46px, 21px);
  font-weight: 380;
  line-height: 1.48;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.9);
}

.reference-hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 42px;
  margin-top: 30px;
}

.reference-primary,
.reference-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 54px;
  font-size: 16px;
  font-weight: 500;
  white-space: nowrap;
  transition: transform 260ms cubic-bezier(0.16, 1, 0.3, 1), background-color 260ms ease, color 260ms ease;
