  --dim: #65685f;
  --line: rgba(245, 246, 239, 0.13);
  --line-strong: rgba(245, 246, 239, 0.28);
  --accent: #fff705;
  --accent-deep: #d9d200;
  --accent-soft: rgba(255, 247, 5, 0.11);
  --ink: #0b0c08;
  --container: 1360px;
  --header-height: 74px;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-snap: cubic-bezier(0.34, 1.56, 0.64, 1);
  --z-header: 30;
  --z-dialog: 60;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 94px;
  background: var(--bg);
}

body {
  margin: 0;
  min-width: 320px;
  overflow-x: clip;
  background:
    linear-gradient(rgba(255, 255, 255, 0.015) 1px, transparent 1px) 0 0 / 100% 80px,
    var(--bg);
  color: var(--text);
  font-family: "Segoe UI Variable", "Aptos", "Segoe UI", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body.menu-open {
  overflow: hidden;
}

::selection {
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
}

img,
iframe {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea {
  color: inherit;
  font: inherit;
}

button {
  cursor: pointer;
}

h1,
h2,
h3,
p,
figure,
fieldset {
  margin: 0;
}

h1,
h2,
h3,
.brand-name,
.button,
.header-cta {
  font-family: "Bahnschrift", "Arial Narrow", "Segoe UI", sans-serif;
}

.container {
  width: min(calc(100% - 64px), var(--container));
  margin-inline: auto;
}

.skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 100;
  padding: 12px 16px;
  background: var(--accent);
  color: var(--ink);
  font-weight: 850;
  transform: translateY(-150%);
  transition: transform 180ms ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: var(--z-header);
  border-bottom: 1px solid transparent;
  background: rgba(5, 6, 5, 0.74);
  backdrop-filter: blur(18px) saturate(130%);
  -webkit-backdrop-filter: blur(18px) saturate(130%);
  transition: border-color 240ms ease, background-color 240ms ease;
}

.site-header.is-scrolled {
  border-color: var(--line);
  background: rgba(5, 6, 5, 0.94);
}

.site-progress {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left center;
  will-change: transform;
}

.header-shell {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 36px;
  width: min(calc(100% - 64px), var(--container));
  min-height: var(--header-height);
  margin-inline: auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  width: fit-content;
}

.brand-mark {
  position: relative;
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  background: var(--accent);
  color: var(--ink);
  font-family: "Bahnschrift", sans-serif;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.brand-mark::after {
  content: "";
  position: absolute;
  right: -5px;
  bottom: -5px;
  width: 10px;
  height: 10px;
  border-right: 1px solid var(--accent);
  border-bottom: 1px solid var(--accent);
}

.brand-name {
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0;
}

.desktop-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 25px;
  min-width: 0;
  white-space: nowrap;
}

.desktop-nav a {
  position: relative;
  padding: 8px 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  transition: color 180ms ease;
}

.desktop-nav a::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 2px;
  left: 0;
  height: 1px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 220ms var(--ease-out);
}

.desktop-nav a:hover,
.desktop-nav a:focus-visible {
  color: var(--text);
}

.desktop-nav a:hover::after,
.desktop-nav a:focus-visible::after {
  transform: scaleX(1);
  transform-origin: left;
}

.header-cta,
.button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 50px;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: 2px;
  padding: 0 21px;
  font-size: 13px;
  font-weight: 850;
  line-height: 1;
  white-space: nowrap;
  isolation: isolate;
  transition: color 220ms ease, border-color 220ms ease, transform 220ms var(--ease-out);
}

.button span,
.button b {
  position: relative;
  z-index: 1;
}

.button b {
  font-family: inherit;
  font-size: 16px;
  font-weight: 500;
}

.header-cta::before,
.button-primary::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #fff;
  transform: translateX(-102%) skewX(-16deg);
  transition: transform 420ms var(--ease-out);
}

.header-cta,
.button-primary {
  background: var(--accent);
  color: var(--ink);
}

.header-cta:hover::before,
.button-primary:hover::before {
  transform: translateX(0) skewX(0);
}

.header-cta:hover,
.button:hover {
  transform: translateY(-2px);
}

.button-secondary {
  border-color: var(--line-strong);
  background: rgba(5, 6, 5, 0.52);
  color: var(--text);
  backdrop-filter: blur(12px);
}

.button-secondary:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.header-cta:active,
.button:active {
  transform: translateY(1px) scale(0.985);
}

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  background: rgba(17, 19, 16, 0.9);
}

.menu-toggle span {
  display: block;
  width: 19px;
  height: 1px;
  margin: 5px auto;
  background: var(--text);
  transition: transform 180ms ease, opacity 180ms ease;
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(6px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-6px) rotate(-45deg);
}

.mobile-nav {
  width: min(calc(100% - 64px), var(--container));
  margin-inline: auto;
  padding: 8px 0 22px;
}

.mobile-nav[hidden] {
  display: none;
}

.mobile-nav a {
  display: block;
  border-bottom: 1px solid var(--line);
  padding: 14px 2px;
  color: var(--muted);
  font-weight: 750;
}

.mobile-nav .mobile-nav-cta {
  margin-top: 14px;
  border: 0;
  padding: 16px;
  background: var(--accent);
  color: var(--ink);
  text-align: center;
}

.hero {
  position: relative;
  min-height: min(760px, calc(1194px - 108px));
  overflow: hidden;
  border-bottom: 1px solid var(--line);
  isolation: isolate;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -3;
  background:
    linear-gradient(90deg, var(--line) 1px, transparent 1px) 0 0 / 120px 100%,
    linear-gradient(var(--line) 1px, transparent 1px) 0 0 / 100% 120px,
    var(--bg);
  opacity: 0.34;
  mask-image: linear-gradient(90deg, #000, transparent 74%);
}

.hero::after {
  content: "";
  position: absolute;
  right: -16%;
  bottom: 18%;
  z-index: 1;
  width: 76%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
  box-shadow: 0 0 24px rgba(255, 247, 5, 0.55);
  transform: rotate(-8deg);
  transform-origin: center;
  opacity: 0.75;
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(500px, 0.92fr) minmax(0, 1.08fr);
  align-items: center;
  min-height: inherit;
}

.hero-content {
  position: relative;
  z-index: 5;
  max-width: 760px;
  padding: 82px 0 100px 56px;
  animation: hero-copy-in 900ms 120ms both var(--ease-out);
}

.hero-kicker,
.section-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--accent);
  font-family: "Bahnschrift", sans-serif;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.hero-kicker > span {
  width: 34px;
  height: 1px;
  background: var(--accent);
  box-shadow: 0 0 12px rgba(255, 247, 5, 0.7);
}

h1 {
  max-width: 760px;
  margin-top: 25px;
  font-size: clamp(58px, 42.951px, 84px);
  font-weight: 900;
  line-height: 0.93;
  letter-spacing: 0;
  text-wrap: balance;
}

h1 span,
h1 em,
h1 small {
  display: block;
  font: inherit;
}

h1 em {
  width: fit-content;
  margin-top: 6px;
  padding: 2px 12px 7px;
