  font-size: 0.62em;
  line-height: 1;
}

.hero-lead {
  max-width: 510px;
  margin-top: 30px;
  color: #c7cac1;
  font-size: 18px;
  line-height: 1.55;
}

.hero-actions {
  display: flex;
  gap: 10px;
  margin-top: 34px;
}

.hero-facts {
  display: grid;
