  margin-top: 58px;
  border-top: 1px solid var(--line-strong);
}

.hero-facts div {
  display: grid;
  gap: 3px;
  padding-top: 14px;
}

.hero-facts div + div {
  border-left: 1px solid var(--line);
  padding-left: 24px;
}

.hero-facts strong {
  font-family: "Bahnschrift", sans-serif;
  font-size: 23px;
  font-weight: 800;
}

.hero-facts span {
  color: var(--dim);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
}

.hero-stage {
  --pointer-x: 0px;
  --pointer-y: 0px;
  position: relative;
  min-width: 0;
  min-height: 650px;
  transform: translate3d(var(--pointer-x), var(--pointer-y), 0);
  transition: transform 180ms ease-out;
  animation: hero-stage-in 1100ms 180ms both var(--ease-out);
  will-change: transform;
}

.stage-frame {
  position: absolute;
  top: 10%;
  right: 3%;
  bottom: 12%;
  left: 15%;
  z-index: 0;
  border: 1px solid rgba(255, 247, 5, 0.4);
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(255, 247, 5, 0.04), transparent 48%),
    #090b0a;
  box-shadow: inset 0 0 90px rgba(255, 247, 5, 0.035), 28px 28px 0 rgba(255, 247, 5, 0.035);
  transform: perspective(1100px) rotateY(-7deg) rotateX(1deg);
  transform-origin: right center;
}

.stage-frame::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 34%;
  background:
    linear-gradient(90deg, rgba(255, 247, 5, 0.35), transparent 32%, rgba(255, 247, 5, 0.2)),
    #11130f;
  clip-path: polygon(0 58%, 100% 0, 100% 100%, 0 100%);
  opacity: 0.55;
}

.stage-grid {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.075) 0 2px, transparent 2px 48px);
  opacity: 0.42;
}

.stage-corner {
  position: absolute;
  width: 42px;
  height: 42px;
}

.stage-corner-a {
  top: -1px;
  left: -1px;
  border-top: 3px solid var(--accent);
  border-left: 3px solid var(--accent);
}

.stage-corner-b {
  right: -1px;
  bottom: -1px;
  border-right: 3px solid var(--accent);
  border-bottom: 3px solid var(--accent);
}

.stage-scan {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 12%;
  background: linear-gradient(90deg, transparent, rgba(255, 247, 5, 0.22), transparent);
  filter: blur(6px);
  opacity: 0.85;
  animation: stage-scan 5.4s infinite ease-in-out;
}

.hero-car {
  position: absolute;
  right: 1%;
  bottom: 8%;
  z-index: 3;
  width: 94%;
  max-width: none;
  height: auto;
  object-fit: contain;
  filter: contrast(1.04) saturate(0.76) drop-shadow(0 34px 28px rgba(0, 0, 0, 0.72));
  animation: car-float 7s 1.2s infinite ease-in-out;
  pointer-events: none;
  user-select: none;
}

.stage-ring {
  position: absolute;
  right: 4%;
  bottom: 4%;
  z-index: 3;
  width: 180px;
  aspect-ratio: 1;
  border: 1px dashed rgba(255, 247, 5, 0.5);
  border-radius: 50%;
  animation: ring-spin 18s infinite linear;
}

.stage-ring::before,
.stage-ring::after,
.stage-ring span {
  content: "";
  position: absolute;
  border-radius: 50%;
}

.stage-ring::before {
  inset: 16px;
  border: 1px solid rgba(255, 255, 255, 0.14);
}

.stage-ring::after {
  top: -4px;
  left: 50%;
  width: 8px;
  height: 8px;
  background: var(--accent);
  box-shadow: 0 0 16px var(--accent);
}

.stage-ring span {
  inset: 48%;
  background: var(--accent);
}

.stage-label {
  position: absolute;
  z-index: 5;
  color: rgba(245, 246, 239, 0.55);
  font-family: Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.13em;
}

.stage-label-top {
  top: 9%;
  left: 10%;
}

.stage-label-top span {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 20px;
  margin-right: 8px;
  background: var(--accent);
  color: var(--ink);
  font-weight: 900;
}

.stage-label-bottom {
  right: 4%;
  bottom: 10%;
}

.stage-badge {
  position: absolute;
  bottom: 8%;
  left: 7%;
  z-index: 5;
  display: grid;
  grid-template-columns: auto auto;
  gap: 12px;
  align-items: center;
  padding: 12px 16px;
  border-left: 2px solid var(--accent);
  background: rgba(5, 6, 5, 0.76);
  backdrop-filter: blur(10px);
}

.stage-badge strong {
  color: var(--accent);
  font-family: "Bahnschrift", sans-serif;
  font-size: 30px;
  line-height: 1;
}

.stage-badge span {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.25;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.hero-scroll {
  position: absolute;
  bottom: 24px;
  left: 56px;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--dim);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.hero-scroll > span {
  position: relative;
  width: 38px;
  height: 1px;
  overflow: hidden;
  background: var(--line-strong);
}

.hero-scroll > span::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--accent);
  animation: scroll-pulse 2.2s infinite ease-in-out;
}

.hero-index {
  position: absolute;
  right: 0;
  bottom: 18px;
  z-index: 6;
  color: rgba(245, 246, 239, 0.3);
  font-family: Consolas, monospace;
  font-size: 10px;
}

.catalog-dock {
  position: relative;
  z-index: 8;
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr);
  min-height: 166px;
  margin-top: -2px;
  border-top: 1px solid var(--line-strong);
  border-bottom: 1px solid var(--line-strong);
  background: rgba(11, 13, 12, 0.94);
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(18px);
}

.catalog-mark {
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-right: 1px solid var(--line);
