  isolation: isolate;
}

.breakout-panel {
  position: absolute;
  top: 34px;
  right: 7%;
  bottom: 16px;
  left: 7%;
  z-index: -1;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  overflow: hidden;
  padding: 24px;
  background: var(--accent);
  color: var(--ink);
  font-family: "Bahnschrift", sans-serif;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.12em;
