.feature-ghost {
  position: absolute;
  top: 8px;
  left: 0;
  z-index: -3;
  color: rgba(245, 246, 239, 0.04);
  font-family: "Bahnschrift", sans-serif;
  font-size: clamp(100px, 100.08px, 180px);
