  font-size: clamp(70px, 83.4px, 148px);
  font-weight: 900;
  white-space: nowrap;
}

.about-layout {
  position: relative;
  display: grid;
  grid-template-columns: minmax(360px, 0.72fr) minmax(0, 1.28fr);
  gap: 72px;
  align-items: start;
}

.about-copy {
  position: sticky;
  top: 112px;
  z-index: 2;
}

.about-copy p,
.guarantee-copy p,
.request-copy > p {
  max-width: 600px;
  margin-top: 27px;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.75;
}

.about-section .about-copy p {
  color: #4e5149;
}

.about-section .section-kicker {
  color: #6f7068;
}

.about-section .text-link {
  color: #0d0f0c;
}

.text-link {
  position: relative;
  display: inline-block;
  margin-top: 30px;
  padding: 0 28px 8px 0;
  border-bottom: 1px solid var(--accent);
  color: var(--text);
  font-family: "Bahnschrift", sans-serif;
  font-weight: 800;
}

.text-link::after {
  content: "↗";
  position: absolute;
  right: 0;
  color: var(--accent);
  transition: transform 220ms var(--ease-out);
}

.text-link:hover::after {
  transform: translate(3px, -3px);
}

.about-visual {
  position: relative;
  overflow: visible;
  border: 1px solid rgba(13, 15, 12, 0.28);
  background: #dfe0d9;
}

.about-visual::before {
  content: "";
  position: absolute;
  top: -18px;
  right: 24px;
  bottom: 18px;
  left: -18px;
  z-index: -1;
  border: 1px solid rgba(255, 247, 5, 0.45);
}

.about-visual img {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  filter: saturate(0.75) contrast(1.07);
}

.about-crosshair {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 2;
  width: 60px;
  height: 60px;
  border: 1px solid rgba(255, 247, 5, 0.58);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  opacity: 0;
  transition: opacity 300ms ease, transform 500ms var(--ease-snap);
}

.about-crosshair::before,
.about-crosshair::after {
  content: "";
  position: absolute;
  background: var(--accent);
}

.about-crosshair::before {
  top: 50%;
  right: -16px;
  left: -16px;
  height: 1px;
}

.about-crosshair::after {
  top: -16px;
  bottom: -16px;
  left: 50%;
  width: 1px;
}

.about-visual:hover .about-crosshair {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1.08);
}

.about-visual figcaption {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 20px;
  color: #65685f;
  font-family: Consolas, monospace;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.about-visual figcaption span:first-child {
  color: var(--accent);
}

.about-index {
  grid-column: 2;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid rgba(13, 15, 12, 0.28);
}

.about-index div {
  position: relative;
  min-height: 126px;
