  top: -1px;
  left: 0;
  width: 18%;
  height: 2px;
  background: var(--accent);
  box-shadow: 0 0 16px rgba(255, 247, 5, 0.7);
  transition: width 1.4s var(--ease-out);
}

.process-track.is-visible::before {
