@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
  }

  .hero-stage {
    transform: none !important;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .site-header,
  .button-secondary,
  .catalog-dock,
  .stage-badge {
    background: var(--bg);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
}


/* SOURCE: premium.css */
/* Premium commercial redesign layer. Core form and interaction styles remain in styles.css. */

:root {
  --bg: #080908;
  --surface: #0e100f;
  --surface-2: #151715;
  --paper: #f1f2ed;
  --paper-strong: #ffffff;
  --text: #f7f8f3;
  --muted: #a9aca4;
  --dim: #74786f;
  --line: rgba(247, 248, 243, 0.14);
  --line-strong: rgba(247, 248, 243, 0.28);
  --accent: #fff705;
  --accent-deep: #dad300;
  --ink: #090a08;
  --container: 1420px;
  --header-height: 72px;
}

body {
  background: var(--bg);
  font-family: "Segoe UI Variable", "Aptos", "Segoe UI", Arial, sans-serif;
}

.container {
  width: min(calc(100% - 72px), var(--container));
}

.site-header {
  position: fixed;
  right: 0;
  left: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: linear-gradient(180deg, rgba(5, 6, 5, 0.9), rgba(5, 6, 5, 0.52));
  backdrop-filter: blur(18px) saturate(125%);
  -webkit-backdrop-filter: blur(18px) saturate(125%);
}

.site-header.is-scrolled {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(7, 8, 7, 0.9);
}

.site-progress {
  height: 1px;
}

.header-shell {
  width: min(calc(100% - 72px), var(--container));
  min-height: var(--header-height);
  gap: 40px;
}

.brand-mark {
  width: 34px;
  height: 34px;
  font-size: 17px;
}

.brand-mark::after {
  display: none;
}

.brand-name {
  font-size: 15px;
}

.desktop-nav {
  gap: clamp(16px, 15.012px, 28px);
}

.desktop-nav a {
  padding-block: 10px;
  color: rgba(247, 248, 243, 0.68);
  font-size: 12px;
  font-weight: 600;
}

.header-cta,
.button {
  min-height: 52px;
  border-radius: 4px;
  padding-inline: 23px;
  font-size: 13px;
}

.header-cta {
  min-height: 44px;
}

.hero {
  position: relative;
  min-height: min(880px, 1194px);
  overflow: hidden;
  border: 0;
  background: #050605;
  isolation: isolate;
}

.hero::before,
.hero::after {
  display: none;
}

.hero-video {
  position: absolute;
  inset: 0;
  z-index: -3;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 53%;
  filter: saturate(0.78) contrast(1.08) brightness(0.78);
  transform: scale(1.015);
}

.hero-scrim {
  position: absolute;
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(90deg, rgba(4, 5, 4, 0.98) 0%, rgba(4, 5, 4, 0.9) 31%, rgba(4, 5, 4, 0.38) 64%, rgba(4, 5, 4, 0.18) 100%),
    linear-gradient(180deg, rgba(4, 5, 4, 0.54) 0%, transparent 31%, rgba(4, 5, 4, 0.78) 100%);
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 0.62fr);
  grid-template-rows: 1fr auto;
  align-items: center;
  min-height: inherit;
  padding-top: var(--header-height);
  padding-bottom: 38px;
}

.hero-content {
  align-self: center;
  max-width: 880px;
  padding: 46px 0 28px;
}

.hero-kicker {
  gap: 0;
  color: var(--text);
  font-size: 13px;
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0;
}

.hero-kicker::before {
  content: "";
  width: 42px;
  height: 2px;
  margin-right: 14px;
  background: var(--accent);
}

.hero-kicker > span {
  display: none;
}

.hero h1 {
  max-width: 900px;
  margin-top: 28px;
  font-family: "Bahnschrift", "Arial Narrow", "Segoe UI", sans-serif;
  font-size: clamp(62px, 60.048px, 112px);
  font-weight: 750;
  line-height: 0.87;
  text-wrap: initial;
}

.hero h1 em {
  margin-top: 8px;
  padding: 0;
  background: transparent;
  color: var(--accent);
  font-style: italic;
  line-height: 1;
  transform: none;
}

.hero h1 small {
  margin-top: 9px;
  color: rgba(247, 248, 243, 0.9);
  font-size: 0.46em;
  font-weight: 520;
  line-height: 1;
}

.hero-lead {
  max-width: 470px;
  margin-top: 28px;
  color: rgba(247, 248, 243, 0.78);
  font-size: 18px;
  line-height: 1.45;
}

.hero-actions {
  gap: 12px;
  margin-top: 32px;
}

.hero .button-secondary {
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(7, 8, 7, 0.36);
}

.hero-facts {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 210px));
  gap: 0;
  max-width: none;
  margin: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
}

.hero-facts div {
  gap: 4px;
  padding: 18px 42px 0 0;
}

.hero-facts div + div {
  border-left: 1px solid rgba(255, 255, 255, 0.14);
  padding-left: 34px;
}

.hero-facts strong {
  font-size: 27px;
  font-weight: 700;
}

.hero-facts span {
  color: rgba(247, 248, 243, 0.54);
  font-size: 12px;
  text-transform: none;
  letter-spacing: 0;
}

.hero-stage,
.hero-scroll,
.hero-index,
.section-number {
  display: none;
}

.catalog-dock {
  z-index: 10;
  grid-template-columns: 150px minmax(0, 1fr);
  min-height: 154px;
  margin-top: 0;
  border: 0;
  background: var(--paper);
  color: var(--ink);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.22);
}

.catalog-mark {
  border-right: 1px solid rgba(9, 10, 8, 0.14);
  padding: 28px;
  color: rgba(9, 10, 8, 0.48);
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
}

.catalog-mark strong {
  margin-top: 2px;
  color: var(--ink);
  font-size: 21px;
}

.catalog-search label > span {
  color: rgba(9, 10, 8, 0.62);
}

.catalog-search input {
  border-color: rgba(9, 10, 8, 0.18);
  background: rgba(255, 255, 255, 0.72);
  color: var(--ink);
}

.catalog-search input::placeholder {
  color: rgba(9, 10, 8, 0.42);
}

.category-tabs button {
  border-color: rgba(9, 10, 8, 0.16);
  background: transparent;
  color: rgba(9, 10, 8, 0.68);
}

.category-tabs button:hover,
.category-tabs button:focus-visible {
  border-color: var(--ink);
  color: var(--ink);
}

.category-tabs a {
  color: var(--ink);
}

.section {
  padding-block: clamp(108px, 83.4px, 170px);
}

.section-heading {
  display: block;
  max-width: 980px;
  margin-bottom: clamp(52px, 50.04px, 88px);
  padding: 0;
}

.section-heading::before {
  display: none;
}

.section-heading h2,
.about-copy h2,
.supplier-copy h2,
.cases-heading h2,
.guarantee-copy h2,
.request-copy h2 {
  font-size: clamp(46px, 50.04px, 88px);
  font-weight: 680;
  line-height: 0.98;
}

.section-kicker {
  margin-bottom: 18px;
  color: var(--accent);
  font-size: 13px;
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0;
}

.advantages-layout {
  grid-template-columns: minmax(0, 1.35fr) minmax(320px, 0.65fr);
  gap: 0;
  align-items: stretch;
}

.advantage-feature {
  min-height: 620px;
  border: 0;
  border-radius: 6px 0 0 6px;
}

.advantage-feature::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 38%, rgba(4, 5, 4, 0.9));
  pointer-events: none;
}

.feature-frame,
.feature-ghost {
  display: none;
}

.advantage-feature-copy {
  z-index: 2;
  right: 42px;
  bottom: 38px;
  left: 42px;
  max-width: 700px;
  border: 0;
  padding: 0;
  background: transparent;
  backdrop-filter: none;
}

.advantage-feature-copy > span {
  margin-bottom: 14px;
  color: var(--accent);
  font-size: 20px;
  text-transform: none;
  letter-spacing: 0;
}

.advantage-feature-copy > span b,
.card-index {
  display: none;
}

.advantage-feature-copy p {
  max-width: 64ch;
  color: rgba(247, 248, 243, 0.75);
  font-size: 15px;
  line-height: 1.65;
}

.advantage-list {
  display: grid;
  grid-template-rows: 1fr 1fr;
  gap: 0;
}

.advantage-list article,
.advantage-list .advantage-accent {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 0;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 0;
  padding: 36px;
  background: #151715;
  color: var(--text);
}

.advantage-list article:first-child {
  border-radius: 0 6px 0 0;
}

.advantage-list .advantage-accent {
  border-bottom: 0;
  border-radius: 0 0 6px 0;
  background: var(--accent);
  color: var(--ink);
}

.advantage-list h3 {
  max-width: 380px;
  font-size: 31px;
  line-height: 1.05;
}

.advantage-list p,
.advantage-list .advantage-accent p {
  margin-top: 16px;
  color: rgba(247, 248, 243, 0.62);
  font-size: 14px;
  line-height: 1.55;
}

.advantage-list .advantage-accent p {
  color: rgba(9, 10, 8, 0.66);
}

.breakout-showcase {
  min-height: 470px;
  margin-top: 110px;
  border: 0;
  border-radius: 6px;
  background: #161815;
  box-shadow: 0 50px 120px rgba(0, 0, 0, 0.34);
  transform: perspective(1400px) rotateX(var(--breakout-y)) rotateY(var(--breakout-x));
}

.breakout-panel {
  top: 0;
  bottom: 0;
  left: 0;
  width: 38%;
  padding: 42px;
  background: var(--accent);
  color: var(--ink);
  clip-path: none;
}

.breakout-panel::before {
  display: none;
}

.breakout-panel span {
  font-family: "Bahnschrift", sans-serif;
  font-size: clamp(54px, 58.38px, 110px);
  font-weight: 750;
  line-height: 0.8;
}

.breakout-track {
  right: 5%;
  bottom: 15%;
  left: 5%;
  height: 1px;
  background: rgba(255, 255, 255, 0.22);
  box-shadow: none;
}

.breakout-showcase > img {
  right: -1.5%;
  bottom: -13%;
  width: 78%;
  filter: saturate(0.8) contrast(1.04) drop-shadow(0 38px 28px rgba(0, 0, 0, 0.7));
}

.about-section {
  position: relative;
  overflow: hidden;
  background: var(--paper);
  color: var(--ink);
}

.about-section::before {
  display: none;
}

.about-layout {
  grid-template-columns: minmax(320px, 0.75fr) minmax(0, 1.25fr);
  gap: clamp(50px, 58.38px, 110px);
  align-items: start;
}

.about-copy {
  position: sticky;
  top: 120px;
  padding-top: 0;
}

.about-copy p {
  max-width: 58ch;
  font-size: 16px;
  line-height: 1.75;
}

.about-section .section-kicker {
  color: rgba(9, 10, 8, 0.55);
}

.about-section .text-link {
  color: var(--ink);
}

.about-visual {
  border: 0;
  border-radius: 6px;
  background: #dcded7;
}

.about-visual::before,
.about-crosshair {
  display: none;
}

.about-visual img {
  aspect-ratio: 1.35;
  object-fit: cover;
}

.about-visual figcaption {
  border-top: 0;
  background: var(--paper-strong);
  color: rgba(9, 10, 8, 0.62);
}

.about-index {
  grid-column: 2;
  margin-top: -24px;
  border-top: 1px solid rgba(9, 10, 8, 0.2);
}

.about-index div + div {
  border-left-color: rgba(9, 10, 8, 0.16);
}

.about-index strong {
  color: var(--ink);
  font-size: clamp(44px, 41.7px, 70px);
}

.about-index span {
  color: rgba(9, 10, 8, 0.52);
}

.process-track {
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line-strong);
  border-bottom: 1px solid var(--line-strong);
}

.process-track::before,
.process-track article::after {
  display: none;
}

.process-track article,
.process-track article:first-child {
  min-height: 260px;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 32px;
}

.process-track article:nth-child(3n) {
  border-right: 0;
}

.process-track article:nth-child(n + 4) {
  border-bottom: 0;
}

.process-track span {
  color: var(--accent);
  font-size: 12px;
}

.process-track h3 {
  margin-top: auto;
  font-size: 28px;
}

.process-track p {
  margin-top: 12px;
  line-height: 1.55;
}

.supplier-section {
  background: #101210;
}

.supplier-layout {
  grid-template-columns: minmax(250px, 0.42fr) minmax(0, 1.58fr);
  gap: clamp(48px, 58.38px, 110px);
  align-items: end;
}

.supplier-copy {
  padding-bottom: 12px;
}

.supplier-copy::before,
.supplier-video::before,
.supplier-video::after {
  display: none;
}

.supplier-copy h2 {
  font-size: clamp(48px, 47.538px, 82px);
}

.supplier-copy .button {
  margin-top: 34px;
}

.supplier-video {
