  color: rgba(255, 255, 255, 0.7);
  font: inherit;
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}

.vehicle-brand-options button:hover,
.vehicle-brand-options button:focus-visible,
.vehicle-brand-options button.is-active {
  outline: none;
