}

.vehicle-brand-empty {
  margin: 0;
  padding: 26px 16px;
  color: rgba(255, 255, 255, 0.42);
  font-size: 13px;
  text-align: center;
}

@keyframes vehicle-brand-popover-in {
  from {
    opacity: 0;
    transform: translateY(-6px);
