.vehicle-picker-divider {
  position: relative;
  height: 48px;
}

.vehicle-picker-divider::before {
  content: "";
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
}

.vehicle-picker-divider span {
  position: absolute;
  top: 50%;
  left: 50%;
  padding: 0 13px;
  background: #0a0d0e;
  color: rgba(255, 255, 255, 0.32);
  font-size: 12px;
  transform: translate(-50%, -50%);
}

.vehicle-part-search {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 126px;
  align-items: end;
  gap: 10px;
}

.vehicle-part-search input {
  padding: 0 18px;
}

.vehicle-part-search input::placeholder {
  color: rgba(255, 255, 255, 0.3);
}

.vehicle-part-search > button,
.vehicle-result-copy button,
.vehicle-request-tray-footer button {
  height: 58px;
  border: 0;
  border-radius: 6px;
  background: radial-gradient(circle at 50% 38%, #fff705 0%, #d8cc00 100%);
  color: #090b0c;
  font: inherit;
  font-size: 14px;
  font-weight: 620;
  cursor: pointer;
  transition: filter 220ms ease, transform 220ms ease;
}

.vehicle-part-search > button:hover,
.vehicle-part-search > button:focus-visible,
.vehicle-result-copy button:hover,
.vehicle-result-copy button:focus-visible,
.vehicle-request-tray-footer button:hover,
.vehicle-request-tray-footer button:focus-visible {
  filter: brightness(0.88);
  transform: translateY(-1px);
}

.vehicle-picker-results {
  margin-top: 42px;
  padding-top: 28px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.vehicle-picker-results > header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.vehicle-picker-results > header div {
  display: flex;
  align-items: baseline;
  gap: 14px;
}

.vehicle-picker-results > header span {
  color: #fff705;
  font-size: 12px;
  font-weight: 650;
}

.vehicle-picker-results > header h3 {
  margin: 0;
  font-size: 24px;
  font-weight: 420;
}

.vehicle-picker-results > header > button {
  padding: 7px 0;
  border: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.48);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.vehicle-result-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.vehicle-result-card {
  display: grid;
  grid-template-columns: 142px minmax(0, 1fr);
  min-height: 178px;
  overflow: hidden;
  border-radius: 6px;
  background: #111416;
}

.vehicle-result-photo {
  min-width: 0;
  background: #0c0e0f;
}

.vehicle-result-photo img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.88) contrast(1.04);
}

.vehicle-result-no-photo {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  color: rgba(255, 255, 255, 0.25);
  font-size: 11px;
  text-align: center;
}

.vehicle-result-copy {
  display: flex;
  min-width: 0;
  padding: 16px;
  flex-direction: column;
}

.vehicle-result-copy p {
  margin: 0 0 8px;
  overflow: hidden;
  color: #fff705;
  font-size: 10px;
  font-weight: 650;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.vehicle-result-copy h4 {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  font-size: 16px;
  font-weight: 480;
  line-height: 1.22;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.vehicle-result-copy small {
  margin-top: 8px;
  color: rgba(255, 255, 255, 0.4);
  font-size: 11px;
}

.vehicle-result-copy > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: auto;
  padding-top: 14px;
}

.vehicle-result-copy strong {
  font-size: 13px;
  font-weight: 570;
}

.vehicle-result-copy button {
  height: 34px;
  padding: 0 12px;
  font-size: 11px;
}

.vehicle-result-copy button.is-added {
  background: rgba(255, 247, 5, 0.12);
  color: #fff705;
}

.vehicle-results-empty {
  margin: 0;
  padding: 36px 0 12px;
  color: rgba(255, 255, 255, 0.56);
  line-height: 1.5;
}

.vehicle-request-tray {
  position: relative;
  display: flex;
  min-width: 0;
  overflow: hidden;
  padding: 34px 28px 28px;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  background:
    radial-gradient(ellipse 95% 55% at 80% 78%, rgba(235, 221, 5, 0.08), transparent 75%),
    #101315;
  flex-direction: column;
}

.vehicle-request-tray::after {
  content: none;
}

.vehicle-request-tray-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding-bottom: 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.vehicle-request-tray-head p {
  margin: 0 0 5px;
  color: rgba(255, 255, 255, 0.5);
  font-size: 12px;
}

.vehicle-request-tray-head strong {
  font-size: 24px;
  font-weight: 430;
}

.vehicle-request-empty {
  position: relative;
  z-index: 2;
  margin-top: 34px;
}

.vehicle-request-empty h3 {
  max-width: 240px;
}

.vehicle-request-empty p {
  max-width: 260px;
  margin: 14px 0 0;
  color: rgba(255, 255, 255, 0.46);
  font-size: 14px;
  line-height: 1.5;
}

.vehicle-request-list {
  position: relative;
  z-index: 2;
  display: grid;
  gap: 8px;
  margin-top: 22px;
}

.vehicle-request-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 14px;
  background: rgba(6, 8, 9, 0.7);
}

.vehicle-request-item div {
  min-width: 0;
}

.vehicle-request-item span {
  display: block;
  margin-bottom: 5px;
  color: #fff705;
  font-size: 9px;
  text-transform: uppercase;
}

.vehicle-request-item strong {
  display: -webkit-box;
  overflow: hidden;
  font-size: 12px;
  font-weight: 460;
  line-height: 1.3;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.vehicle-request-item > button {
  flex: 0 0 auto;
  border: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.5);
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
}

.vehicle-request-tray-footer {
  position: relative;
  z-index: 2;
  margin-top: auto;
  padding-top: 32px;
}

.vehicle-request-tray-footer p {
  margin: 0 0 16px;
  color: rgba(255, 255, 255, 0.38);
  font-size: 11px;
  line-height: 1.45;
}

.vehicle-request-tray-footer button {
  width: 100%;
}

.vehicle-request-tray-footer button:disabled {
  background: rgba(255, 255, 255, 0.07);
  color: rgba(255, 255, 255, 0.3);
  cursor: not-allowed;
  filter: none;
  transform: none;
}


  .vehicle-picker {
