  border: 1px solid var(--line-strong);
  border-radius: 2px;
  padding: 0 14px;
  background: var(--surface-2);
}

.dialog-body {
  min-height: 0;
  padding: 24px 26px 34px;
  overflow-y: auto;
}

.dialog-body h3 {
  margin-top: 25px;
  color: var(--accent);
  font-size: 16px;
}

.dialog-body p {
  margin-top: 10px;
  color: var(--muted);
  line-height: 1.7;
}

.dialog-body a {
  color: var(--accent);
}

[hidden] {
  display: none !important;
}

[data-reveal] {
  opacity: 0;
  transform: translateY(42px);
  transition: opacity 850ms var(--ease-out), transform 850ms var(--ease-out);
  transition-delay: var(--reveal-delay, 0ms);
}

[data-reveal="scale"] {
  transform: translateY(28px) scale(0.975);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

@keyframes hero-copy-in {
  from {
    opacity: 0;
    transform: translate3d(-36px, 0, 0);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes hero-stage-in {
  from {
    opacity: 0;
    transform: translate3d(70px, 0, 0) scale(0.96);
  }
  to {
    opacity: 1;
  }
}

@keyframes car-float {
  0%,
  100% {
    translate: 0 0;
  }
  50% {
    translate: -8px -10px;
  }
}

@keyframes stage-scan {
  0%,
  100% {
    left: 7%;
    opacity: 0;
  }
  18%,
  82% {
    opacity: 0.65;
  }
  50% {
    left: 92%;
  }
}

@keyframes ring-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes scroll-pulse {
  0% {
    transform: translateX(-105%);
  }
  55%,
  100% {
    transform: translateX(105%);
  }
}









@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
  }

  .hero-stage {
    transform: none !important;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .site-header,
  .button-secondary,
  .catalog-dock,
  .stage-badge {
    background: var(--bg);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
}


/* SOURCE: premium.css */
/* Premium commercial redesign layer. Core form and interaction styles remain in styles.css. */

:root {
  --bg: #080908;
  --surface: #0e100f;
  --surface-2: #151715;
  --paper: #f1f2ed;
  --paper-strong: #ffffff;
  --text: #f7f8f3;
  --muted: #a9aca4;
  --dim: #74786f;
  --line: rgba(247, 248, 243, 0.14);
  --line-strong: rgba(247, 248, 243, 0.28);
  --accent: #fff705;
  --accent-deep: #dad300;
  --ink: #090a08;
  --container: 1420px;
  --header-height: 72px;
}

body {
  background: var(--bg);
  font-family: "Segoe UI Variable", "Aptos", "Segoe UI", Arial, sans-serif;
}

.container {
  width: min(calc(100% - 72px), var(--container));
}

.site-header {
  position: fixed;
  right: 0;
  left: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: linear-gradient(180deg, rgba(5, 6, 5, 0.9), rgba(5, 6, 5, 0.52));
  backdrop-filter: blur(18px) saturate(125%);
  -webkit-backdrop-filter: blur(18px) saturate(125%);
}

.site-header.is-scrolled {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(7, 8, 7, 0.9);
}

.site-progress {
  height: 1px;
}

.header-shell {
  width: min(calc(100% - 72px), var(--container));
  min-height: var(--header-height);
  gap: 40px;
}

.brand-mark {
  width: 34px;
  height: 34px;
  font-size: 17px;
}

.brand-mark::after {
  display: none;
}

.brand-name {
  font-size: 15px;
}

.desktop-nav {
  gap: clamp(16px, 34.56px, 28px);
}

.desktop-nav a {
  padding-block: 10px;
  color: rgba(247, 248, 243, 0.68);
  font-size: 12px;
  font-weight: 600;
}

.header-cta,
.button {
  min-height: 52px;
  border-radius: 4px;
  padding-inline: 23px;
  font-size: 13px;
}

.header-cta {
  min-height: 44px;
}

.hero {
  position: relative;
  min-height: min(880px, 1080px);
  overflow: hidden;
  border: 0;
  background: #050605;
  isolation: isolate;
}

.hero::before,
.hero::after {
  display: none;
}

.hero-video {
  position: absolute;
  inset: 0;
  z-index: -3;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 53%;
  filter: saturate(0.78) contrast(1.08) brightness(0.78);
  transform: scale(1.015);
}

.hero-scrim {
  position: absolute;
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(90deg, rgba(4, 5, 4, 0.98) 0%, rgba(4, 5, 4, 0.9) 31%, rgba(4, 5, 4, 0.38) 64%, rgba(4, 5, 4, 0.18) 100%),
    linear-gradient(180deg, rgba(4, 5, 4, 0.54) 0%, transparent 31%, rgba(4, 5, 4, 0.78) 100%);
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 0.62fr);
  grid-template-rows: 1fr auto;
  align-items: center;
  min-height: inherit;
  padding-top: var(--header-height);
  padding-bottom: 38px;
}

.hero-content {
  align-self: center;
  max-width: 880px;
  padding: 46px 0 28px;
}

.hero-kicker {
  gap: 0;
  color: var(--text);
  font-size: 13px;
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0;
}

.hero-kicker::before {
  content: "";
  width: 42px;
  height: 2px;
  margin-right: 14px;
  background: var(--accent);
}

.hero-kicker > span {
  display: none;
}

.hero h1 {
  max-width: 900px;
  margin-top: 28px;
  font-family: "Bahnschrift", "Arial Narrow", "Segoe UI", sans-serif;
  font-size: clamp(62px, 138.24px, 112px);
  font-weight: 750;
  line-height: 0.87;
  text-wrap: initial;
}

.hero h1 em {
  margin-top: 8px;
  padding: 0;
  background: transparent;
  color: var(--accent);
  font-style: italic;
  line-height: 1;
  transform: none;
}

.hero h1 small {
  margin-top: 9px;
  color: rgba(247, 248, 243, 0.9);
  font-size: 0.46em;
  font-weight: 520;
  line-height: 1;
}

.hero-lead {
  max-width: 470px;
  margin-top: 28px;
  color: rgba(247, 248, 243, 0.78);
  font-size: 18px;
  line-height: 1.45;
}

.hero-actions {
  gap: 12px;
  margin-top: 32px;
}

.hero .button-secondary {
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(7, 8, 7, 0.36);
}

.hero-facts {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 210px));
  gap: 0;
  max-width: none;
  margin: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
}

.hero-facts div {
  gap: 4px;
  padding: 18px 42px 0 0;
}

.hero-facts div + div {
  border-left: 1px solid rgba(255, 255, 255, 0.14);
  padding-left: 34px;
}

.hero-facts strong {
  font-size: 27px;
  font-weight: 700;
}

.hero-facts span {
  color: rgba(247, 248, 243, 0.54);
  font-size: 12px;
  text-transform: none;
  letter-spacing: 0;
}

.hero-stage,
.hero-scroll,
.hero-index,
.section-number {
  display: none;
}

.catalog-dock {
  z-index: 10;
  grid-template-columns: 150px minmax(0, 1fr);
  min-height: 154px;
  margin-top: 0;
  border: 0;
  background: var(--paper);
  color: var(--ink);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.22);
}

.catalog-mark {
  border-right: 1px solid rgba(9, 10, 8, 0.14);
  padding: 28px;
  color: rgba(9, 10, 8, 0.48);
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
}

.catalog-mark strong {
  margin-top: 2px;
  color: var(--ink);
  font-size: 21px;
}

.catalog-search label > span {
  color: rgba(9, 10, 8, 0.62);
}

.catalog-search input {
  border-color: rgba(9, 10, 8, 0.18);
  background: rgba(255, 255, 255, 0.72);
  color: var(--ink);
}

.catalog-search input::placeholder {
  color: rgba(9, 10, 8, 0.42);
}

.category-tabs button {
  border-color: rgba(9, 10, 8, 0.16);
  background: transparent;
  color: rgba(9, 10, 8, 0.68);
}

.category-tabs button:hover,
.category-tabs button:focus-visible {
  border-color: var(--ink);
  color: var(--ink);
}

.category-tabs a {
  color: var(--ink);
}

.section {
  padding-block: clamp(108px, 192px, 170px);
}

.section-heading {
  display: block;
  max-width: 980px;
  margin-bottom: clamp(52px, 115.2px, 88px);
  padding: 0;
}

.section-heading::before {
  display: none;
}

.section-heading h2,
.about-copy h2,
.supplier-copy h2,
.cases-heading h2,
.guarantee-copy h2,
.request-copy h2 {
  font-size: clamp(46px, 115.2px, 88px);
  font-weight: 680;
  line-height: 0.98;
}

.section-kicker {
  margin-bottom: 18px;
  color: var(--accent);
  font-size: 13px;
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0;
}

.advantages-layout {
  grid-template-columns: minmax(0, 1.35fr) minmax(320px, 0.65fr);
  gap: 0;
  align-items: stretch;
}

.advantage-feature {
  min-height: 620px;
  border: 0;
  border-radius: 6px 0 0 6px;
}

.advantage-feature::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 38%, rgba(4, 5, 4, 0.9));
  pointer-events: none;
}

.feature-frame,
.feature-ghost {
  display: none;
}

.advantage-feature-copy {
  z-index: 2;
  right: 42px;
  bottom: 38px;
  left: 42px;
  max-width: 700px;
  border: 0;
  padding: 0;
  background: transparent;
  backdrop-filter: none;
}

.advantage-feature-copy > span {
  margin-bottom: 14px;
  color: var(--accent);
  font-size: 20px;
  text-transform: none;
  letter-spacing: 0;
}

.advantage-feature-copy > span b,
.card-index {
  display: none;
}

.advantage-feature-copy p {
  max-width: 64ch;
  color: rgba(247, 248, 243, 0.75);
  font-size: 15px;
  line-height: 1.65;
}

.advantage-list {
  display: grid;
  grid-template-rows: 1fr 1fr;
  gap: 0;
}

.advantage-list article,
.advantage-list .advantage-accent {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 0;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 0;
  padding: 36px;
  background: #151715;
  color: var(--text);
}

.advantage-list article:first-child {
  border-radius: 0 6px 0 0;
}

.advantage-list .advantage-accent {
  border-bottom: 0;
  border-radius: 0 0 6px 0;
  background: var(--accent);
  color: var(--ink);
}

.advantage-list h3 {
  max-width: 380px;
  font-size: 31px;
  line-height: 1.05;
}

.advantage-list p,
.advantage-list .advantage-accent p {
  margin-top: 16px;
  color: rgba(247, 248, 243, 0.62);
  font-size: 14px;
  line-height: 1.55;
}

.advantage-list .advantage-accent p {
  color: rgba(9, 10, 8, 0.66);
}

.breakout-showcase {
  min-height: 470px;
  margin-top: 110px;
  border: 0;
  border-radius: 6px;
  background: #161815;
  box-shadow: 0 50px 120px rgba(0, 0, 0, 0.34);
  transform: perspective(1400px) rotateX(var(--breakout-y)) rotateY(var(--breakout-x));
}

.breakout-panel {
  top: 0;
  bottom: 0;
  left: 0;
  width: 38%;
  padding: 42px;
  background: var(--accent);
  color: var(--ink);
  clip-path: none;
}

.breakout-panel::before {
  display: none;
}

.breakout-panel span {
  font-family: "Bahnschrift", sans-serif;
  font-size: clamp(54px, 134.4px, 110px);
  font-weight: 750;
  line-height: 0.8;
}

.breakout-track {
  right: 5%;
  bottom: 15%;
  left: 5%;
  height: 1px;
  background: rgba(255, 255, 255, 0.22);
  box-shadow: none;
}

.breakout-showcase > img {
  right: -1.5%;
  bottom: -13%;
  width: 78%;
  filter: saturate(0.8) contrast(1.04) drop-shadow(0 38px 28px rgba(0, 0, 0, 0.7));
}

.about-section {
  position: relative;
  overflow: hidden;
  background: var(--paper);
  color: var(--ink);
}

.about-section::before {
  display: none;
}

.about-layout {
  grid-template-columns: minmax(320px, 0.75fr) minmax(0, 1.25fr);
  gap: clamp(50px, 134.4px, 110px);
  align-items: start;
}

.about-copy {
  position: sticky;
  top: 120px;
  padding-top: 0;
}

.about-copy p {
  max-width: 58ch;
  font-size: 16px;
  line-height: 1.75;
}

.about-section .section-kicker {
  color: rgba(9, 10, 8, 0.55);
}

.about-section .text-link {
  color: var(--ink);
}

.about-visual {
  border: 0;
  border-radius: 6px;
  background: #dcded7;
}

.about-visual::before,
.about-crosshair {
  display: none;
}

.about-visual img {
  aspect-ratio: 1.35;
  object-fit: cover;
}

.about-visual figcaption {
  border-top: 0;
  background: var(--paper-strong);
  color: rgba(9, 10, 8, 0.62);
}

.about-index {
  grid-column: 2;
  margin-top: -24px;
  border-top: 1px solid rgba(9, 10, 8, 0.2);
}

.about-index div + div {
  border-left-color: rgba(9, 10, 8, 0.16);
}

.about-index strong {
  color: var(--ink);
  font-size: clamp(44px, 96px, 70px);
}

.about-index span {
  color: rgba(9, 10, 8, 0.52);
}

.process-track {
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line-strong);
  border-bottom: 1px solid var(--line-strong);
}

.process-track::before,
.process-track article::after {
  display: none;
}

.process-track article,
.process-track article:first-child {
  min-height: 260px;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 32px;
}

.process-track article:nth-child(3n) {
  border-right: 0;
}

.process-track article:nth-child(n + 4) {
  border-bottom: 0;
}

.process-track span {
  color: var(--accent);
  font-size: 12px;
}

.process-track h3 {
  margin-top: auto;
  font-size: 28px;
}

.process-track p {
  margin-top: 12px;
  line-height: 1.55;
}

.supplier-section {
  background: #101210;
}

.supplier-layout {
  grid-template-columns: minmax(250px, 0.42fr) minmax(0, 1.58fr);
  gap: clamp(48px, 134.4px, 110px);
  align-items: end;
}

.supplier-copy {
  padding-bottom: 12px;
}

.supplier-copy::before,
.supplier-video::before,
.supplier-video::after {
  display: none;
}

.supplier-copy h2 {
  font-size: clamp(48px, 109.44px, 82px);
}

.supplier-copy .button {
  margin-top: 34px;
}

.supplier-video {
  overflow: hidden;
  border: 0;
  border-radius: 6px;
  background: #000;
}

.cases-heading {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  margin-bottom: 54px;
}

.cases-heading > div {
  align-items: flex-end;
}

.cases-grid {
  gap: 16px;
}

.case-card {
  overflow: hidden;
  border: 0;
  border-radius: 6px;
}

.case-card::before,
.case-card::after {
  display: none;
}

.case-card img {
  filter: saturate(0.76) contrast(1.03);
}

.case-card:hover img {
  filter: saturate(1) contrast(1.03);
  transform: scale(1.035);
}

.case-copy {
  right: 24px;
  bottom: 24px;
  left: 24px;
  border: 0;
  border-radius: 4px;
  background: rgba(7, 8, 7, 0.78);
  backdrop-filter: blur(14px);
}

.case-copy span {
  color: var(--accent);
  letter-spacing: 0;
}

.guarantee-section {
  background: var(--paper);
  color: var(--ink);
}

.guarantee-layout {
  grid-template-columns: minmax(300px, 0.6fr) minmax(0, 1.4fr);
  gap: clamp(50px, 153.6px, 120px);
}

.guarantee-copy p {
  color: rgba(9, 10, 8, 0.62);
  font-size: 16px;
  line-height: 1.7;
}

.guarantee-grid {
  gap: 0;
  border-top: 1px solid rgba(9, 10, 8, 0.18);
}

.guarantee-grid article,
.guarantee-grid article:nth-child(2),
.guarantee-grid article:hover {
  min-height: 230px;
  border: 0;
  border-right: 1px solid rgba(9, 10, 8, 0.14);
  border-bottom: 1px solid rgba(9, 10, 8, 0.14);
  padding: 30px;
  background: transparent;
  color: var(--ink);
}

.guarantee-grid article:nth-child(2n) {
  border-right: 0;
}

.guarantee-grid article::before {
  background: var(--accent);
}

.guarantee-grid article p,
.guarantee-grid article:nth-child(2) p,
.guarantee-grid article:hover p {
  color: rgba(9, 10, 8, 0.58);
}

.faq-section {
  grid-template-columns: minmax(300px, 0.55fr) minmax(0, 1.45fr);
  gap: clamp(50px, 153.6px, 130px);
}

.faq-section .section-heading {
  position: sticky;
  top: 120px;
  align-self: start;
  margin: 0;
  padding: 0;
  border: 0;
}

.faq-section .section-heading::before {
  display: none;
}

.faq-list details {
  border-color: var(--line-strong);
}

.faq-list summary {
  padding-block: 25px;
  font-size: 21px;
}

.faq-list summary::after {
  border-color: var(--line-strong);
  border-radius: 50%;
}

.request-section {
  overflow: hidden;
  background: #111310;
}

.request-section::before {
  top: -10%;
  right: -8%;
  width: 46%;
  height: 120%;
  background: var(--accent);
  clip-path: polygon(30% 0, 100% 0, 100% 100%, 0 100%);
  opacity: 1;
  transform: none;
}

.request-layout {
  grid-template-columns: minmax(300px, 0.7fr) minmax(520px, 1.3fr);
  gap: clamp(50px, 153.6px, 120px);
}

.request-copy::after {
  display: none;
}

.request-form {
  border: 0;
  border-radius: 6px;
  background: rgba(6, 7, 6, 0.95);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.32);
}

.request-form::before {
  height: 3px;
}

.contacts-section {
  padding-bottom: 100px;
}

.contacts-grid {
  gap: 0;
  border-top: 1px solid var(--line-strong);
}

.contacts-grid article {
  min-height: 210px;
  border: 0;
  border-right: 1px solid var(--line);
  padding: 28px;
  background: transparent;
}

.contacts-grid article:last-child {
  border-right: 0;
}

.contacts-grid .contact-action {
  align-items: flex-end;
  justify-content: flex-end;
}

.site-footer {
  border-top: 1px solid var(--line);
  background: #050605;
}

[data-reveal] {
  transform: translateY(26px);
  transition-duration: 900ms;
}

[data-reveal="scale"] {
  transform: translateY(30px) scale(0.985);
}







@media (prefers-reduced-motion: reduce) {
  .hero-video {
    display: none;
  }

  .hero {
    background: #050605 url("./source-dist2/images/car1.jpg") center / cover no-repeat;
  }
}

/* First-screen art direction: approved block-by-block workflow. */
.hero {
  min-height: 1080px;
  background: #050605;
}

.hero-scrim {
  background:
    radial-gradient(circle at 77% 74%, rgba(255, 247, 5, 0.09), transparent 31%),
    linear-gradient(180deg, #050605 0%, #050605 64%, #090b08 100%);
}

.hero-grid {
  position: relative;
  display: block;
  min-height: 1080px;
  padding-top: 112px;
  padding-bottom: 38px;
}

.hero-content {
  position: relative;
  z-index: 5;
  max-width: 1080px;
  padding: 0;
}

.hero h1 {
  max-width: 1080px;
  margin-top: 24px;
  font-size: clamp(72px, 141.12px, 112px);
  font-weight: 680;
  line-height: 0.82;
  text-transform: uppercase;
}

.hero h1 em {
  margin-top: 14px;
  font-style: normal;
}

.hero h1 small {
  display: inline-block;
  margin: 0 0 0 28px;
  color: var(--text);
  font-size: 0.43em;
  font-weight: 560;
  text-transform: none;
  vertical-align: 0.12em;
}

.hero-lead {
  position: absolute;
  top: 310px;
  right: 0;
  z-index: 6;
  width: min(480px, 330px);
  margin: 0;
  color: rgba(247, 248, 243, 0.74);
  font-size: 16px;
  line-height: 1.55;
}

.hero-facts {
  position: absolute;
  bottom: 166px;
  left: 0;
  z-index: 7;
  grid-template-columns: repeat(3, minmax(0, 150px));
  width: auto;
  border: 0;
}

.hero-facts div,
.hero-facts div + div {
  padding: 0 26px 0 0;
  border: 0;
}

.hero-facts div + div {
  padding-left: 26px;
  border-left: 1px solid rgba(255, 255, 255, 0.2);
}

.hero-facts strong {
  color: var(--accent);
  font-size: 27px;
}

.hero-facts span {
  color: rgba(247, 248, 243, 0.74);
  font-size: 12px;
}

.hero .hero-stage {
  --pointer-x: 0px;
  --pointer-y: 0px;
  position: absolute;
  right: -18px;
  bottom: 26px;
  z-index: 3;
  display: block;
  width: min(1113.6px, 820px);
  min-height: 420px;
  transform: translate3d(var(--pointer-x), var(--pointer-y), 0);
  transition: transform 180ms ease-out;
  animation: hero-stage-in 1100ms 180ms both var(--ease-out);
}

.hero .stage-frame {
  position: absolute;
  inset: 42px 0 0 9%;
  z-index: 0;
  overflow: hidden;
  border: 1px solid rgba(255, 247, 5, 0.35);
  border-radius: 5px;
  background: #0d0f0d;
  box-shadow:
    inset 0 0 80px rgba(255, 247, 5, 0.035),
    0 36px 90px rgba(0, 0, 0, 0.46);
  transform: none;
}

.hero .stage-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  border-top: 2px solid var(--accent);
  opacity: 0.68;
}

.hero .stage-frame::after {
  right: 0;
  bottom: 0;
  left: 0;
  height: 34%;
  background: linear-gradient(180deg, transparent, rgba(255, 247, 5, 0.08));
  clip-path: none;
  opacity: 1;
}

.hero .stage-grid {
  inset: 0;
  background: repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.055) 0 1px, transparent 1px 58px);
  opacity: 0.7;
}

.hero .hero-car {
  right: -7%;
  bottom: -5%;
  z-index: 3;
  width: 108%;
  filter: saturate(0.72) contrast(1.05) drop-shadow(0 36px 26px rgba(0, 0, 0, 0.72));
  animation: car-float 7s 1.2s infinite ease-in-out;
}

.hero-actions {
  position: absolute;
  bottom: 38px;
  left: 0;
  z-index: 8;
  margin: 0;
}

