  font-size: 14px;
  line-height: 1.55;
}

.catalog-preview-disclaimer p,
.catalog-preview-disclaimer span {
  margin: 0;
}

.catalog-preview-disclaimer > p {
  padding: 22px 36px 0;
}

.catalog-preview-disclaimer > div {
  display: grid;
  gap: 18px;
  padding: 22px 28px 0;
}

.catalog-preview-disclaimer a {
  position: relative;
  isolation: isolate;
  flex: 0 0 auto;
  display: inline-flex;
  min-height: 54px;
  width: 100%;
  padding: 0 24px;
